_file_map = {

    "analysis_3_analyze.baml": "// Fase 3 — Analyze Explainability Requirements\n// Taxonomias e matriz de viabilidade: OpenUPExp/tarefas/analisar-requisito.md (passos 1–7).\n// O template de Requisitos de Explicabilidade Refinados (RER) está marcado \"???Validar\" na\n// teoria; os campos abaixo seguem as \"perguntas úteis\" do passo 1 (provisório, A-14/A-15).\n\n// ---------------------------------------------------------------------------\n// Taxonomias do passo 2, passo 3 e passo 6 (A-15: fechadas, com OUTRO justificado)\n// ---------------------------------------------------------------------------\n\nenum ExplanatoryAspect {\n  COMPREENSAO @description(\"entender resultado\")\n  JUSTIFICATIVA @description(\"justificar decisão\")\n  CONFIANCA @description(\"aumentar aceitação\")\n  AUDITORIA @description(\"verificar comportamento\")\n  CONTESTACAO @description(\"questionar decisão\")\n  APRENDIZADO @description(\"ensinar funcionamento\")\n  OUTRO @description(\"Outro aspecto; justifique\")\n}\n\nenum ExplanationType {\n  FEATURE_IMPORTANCE @description(\"Importância dos atributos\")\n  LOCAL @description(\"Explicar caso específico\")\n  GLOBAL @description(\"Explicar comportamento geral\")\n  EXAMPLE_BASED @description(\"Demonstrar exemplos semelhantes\")\n  RULE_BASED @description(\"Mostrar regras\")\n  COUNTERFACTUAL @description(\"Mostrar impacto dos atributos (e se...?)\")\n  OUTRO @description(\"Outro tipo; justifique\")\n}\n\nenum DecisionRisk {\n  ALTO\n  MEDIO\n  BAIXO\n}\n\nenum ConflictKind {\n  ENTRE_STAKEHOLDERS @description(\"Ex.: usuários querem explicações simples; auditores, alto detalhamento\")\n  TRANSPARENCIA_PRIVACIDADE @description(\"Transparência × privacidade\")\n  DETALHAMENTO_DESEMPENHO @description(\"Explicações mais detalhadas × desempenho\")\n  OUTRO\n}\n\nenum ConstraintKind {\n  REGULATORIA\n  ETICA\n  TECNICA\n  ORGANIZACIONAL\n  OUTRA\n}\n\nenum FeasibilityCriterion {\n  TECNICA\n  REGULATORIA\n  OPERACIONAL\n  ECONOMICA\n}\n\nenum FeasibilityStatus {\n  SIM\n  NAO\n  NAO_AVALIADO @description(\"Sem informação suficiente nas entradas; registre Lacuna\")\n}\n\nenum MoSCoW {\n  MUST @description(\"Essencial para os objetivos mínimos de explicabilidade\")\n  SHOULD @description(\"Importante, mas a ausência não inviabiliza o sistema\")\n  COULD @description(\"Desejável; pode ser adiado\")\n  WONT @description(\"Reconhecido, fora do escopo da iteração ou versão atual\")\n}\n\nclass RequirementIndexEntry {\n  id string\n  enunciado string\n}\n\n// ---------------------------------------------------------------------------\n// 3.1.2 Consolidate and Characterize Requirements — por requisito (map)\n// ---------------------------------------------------------------------------\n\nclass CharacterizedRequirement {\n  id string? @description(\"RER-n existente; null se novo\")\n  req_id string @description(\"REQ-n caracterizado\")\n  contexto_uso string? @description(\"Em qual contexto a explicação será utilizada\")\n  usuarios_explicacao string[] @description(\"STK-n que utilizarão a explicação\")\n  decisao_apoiada string? @description(\"Qual decisão está sendo apoiada pelo sistema\")\n  risco_decisao DecisionRisk? @description(\"Risco/impacto da decisão; null se as entradas não sustentarem\")\n  objetivo_principal string? @description(\"Objetivo principal da explicação\")\n  obrigacao_regulatoria bool? @description(\"Existe obrigação regulatória de explicar? null se não houver evidência\")\n  requisitos_regulatorios string[] @description(\"REQ-n complementares ou normas citadas nas entradas que se associam\")\n  lacunas Lacuna[]\n}\n\nclass CharacterizedRequirementsArtifact {\n  caracterizacoes CharacterizedRequirement[]\n}\n\nclass CharacterizeInput {\n  requisito ConsolidatedRequirement\n  stakeholders Stakeholder[]\n  necessidades ExplainabilityNeed[]\n  requisitos_complementares ConsolidatedRequirement[]\n  caracterizacao_existente CharacterizedRequirement?\n}\n\nfunction CharacterizeRequirement(entrada: CharacterizeInput, contexto: ContextItem[]) -> CharacterizedRequirement {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 3.1.2 \"Consolidate and Characterize Requirements\" do OpenUPExp para\n    UM requisito de explicabilidade: compreender seu contexto de uso e seus objetivos.\n\n    {{ RegrasNaoInvencao() }}\n\n    PERGUNTAS A RESPONDER (somente com base nas entradas)\n    - Quem utilizará a explicação?\n    - Qual decisão está sendo apoiada?\n    - Qual o risco associado à decisão?\n    - Qual o objetivo principal da explicação?\n    - Existe obrigação regulatória para explicar a decisão?\n\n    REGRAS ESPECÍFICAS\n    - req_id = o id do requisito da entrada.\n    - Campos sem evidência ficam null e geram Lacuna com pergunta sugerida.\n    - Mantenha o id da caracterização existente, se houver.\n\n    {{ _.role(\"user\") }}\n    REQUISITO\n    {{ entrada.requisito }}\n\n    STAKEHOLDERS ENVOLVIDOS\n    {{ entrada.stakeholders }}\n\n    NECESSIDADES DA VISÃO RELACIONADAS\n    {{ entrada.necessidades }}\n\n    REQUISITOS COMPLEMENTARES (normas, restrições)\n    {{ entrada.requisitos_complementares }}\n\n    CARACTERIZAÇÃO EXISTENTE\n    {{ entrada.caracterizacao_existente }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 3.2.1 Classify Explainability Aspects — em lotes de requisitos\n// ---------------------------------------------------------------------------\n\nclass AspectClassification {\n  id string? @description(\"ASP-n existente; null se novo\")\n  req_id string\n  aspectos ExplanatoryAspect[] @description(\"Classificação múltipla permitida\")\n  predominante ExplanatoryAspect\n  justificativa string\n  lacunas Lacuna[]\n}\n\nclass AspectsArtifact {\n  classificacoes AspectClassification[]\n}\n\nclass ClassifyAspectsInput {\n  requisitos ConsolidatedRequirement[]\n  caracterizacoes CharacterizedRequirement[]\n  classificacoes_existentes AspectClassification[]\n}\n\nfunction ClassifyExplainabilityAspects(entrada: ClassifyAspectsInput, contexto: ContextItem[]) -> AspectsArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 3.2.1 \"Classify Explainability Aspects\" do OpenUPExp: classificar cada\n    requisito pelo aspecto explicativo predominante.\n\n    {{ RegrasNaoInvencao() }}\n\n    REGRAS ESPECÍFICAS\n    - Exatamente uma classificação por requisito da entrada (req_id = REQ-n).\n    - Pode haver mais de um aspecto; indique o predominante.\n    - Não assuma que todos os stakeholders têm os mesmos objetivos.\n    - Use OUTRO só com justificativa explícita.\n\n    {{ _.role(\"user\") }}\n    REQUISITOS\n    {{ entrada.requisitos }}\n\n    CARACTERIZAÇÕES (3.1.2)\n    {{ entrada.caracterizacoes }}\n\n    CLASSIFICAÇÕES EXISTENTES\n    {{ entrada.classificacoes_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 3.2.2 Associate Requirements with Explanation Types — em lotes, com a base de referência\n// ---------------------------------------------------------------------------\n\nclass ExplanationTypeMapping {\n  id string? @description(\"MAP-n existente; null se novo\")\n  req_id string\n  tipos ExplanationType[]\n  justificativa string @description(\"Por que esses tipos atendem ao perfil, ao contexto e ao objetivo\")\n  evidencias EvidenceRef[] @description(\"Opcional: trechos da base de referência que sustentam o mapeamento\")\n  lacunas Lacuna[]\n}\n\nclass ExplanationTypesArtifact {\n  mapeamentos ExplanationTypeMapping[]\n}\n\nclass MapTypesInput {\n  requisitos ConsolidatedRequirement[]\n  caracterizacoes CharacterizedRequirement[]\n  aspectos AspectClassification[]\n  mapeamentos_existentes ExplanationTypeMapping[]\n}\n\nfunction AssociateExplanationTypes(entrada: MapTypesInput, contexto: ContextItem[]) -> ExplanationTypesArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 3.2.2 \"Associate Requirements with Explanation Types\" do OpenUPExp:\n    associar cada requisito a um ou mais tipos de explicação com maior aderência ao perfil do\n    stakeholder, ao contexto da decisão e ao objetivo da explicação.\n\n    {{ RegrasNaoInvencao() }}\n\n    REGRAS ESPECÍFICAS\n    - Exatamente um mapeamento por requisito da entrada.\n    - NÃO selecione ferramentas, bibliotecas ou algoritmos específicos: apenas o tipo de explicação.\n    - Exceção à regra 1 de rigor: você pode usar os trechos recuperados da base de referência para\n      fundamentar o tipo; cite-os em evidencias (chunk_ref exato, citação literal).\n    - Registre a justificativa e as limitações conhecidas como Lacuna.\n\n    {{ _.role(\"user\") }}\n    REQUISITOS\n    {{ entrada.requisitos }}\n\n    CARACTERIZAÇÕES\n    {{ entrada.caracterizacoes }}\n\n    ASPECTOS EXPLICATIVOS (3.2.1)\n    {{ entrada.aspectos }}\n\n    MAPEAMENTOS EXISTENTES\n    {{ entrada.mapeamentos_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 3.2.3 Analyze Conflicts — sobre pares candidatos (cobertura de pares registrada)\n// ---------------------------------------------------------------------------\n\nclass RequirementPair {\n  a string\n  b string\n  motivo string @description(\"Por que o par foi selecionado para verificação\")\n}\n\nclass RequirementConflict {\n  id string? @description(\"CNF-n existente; null se novo\")\n  req_ids string[] @description(\"Dois ou mais REQ-n em conflito\")\n  tipo ConflictKind\n  descricao string\n  stakeholder_ids string[]\n  alternativas_resolucao string[] @description(\"Alternativas propostas; a decisão é dos stakeholders\")\n}\n\nclass ConflictsArtifact {\n  conflitos RequirementConflict[]\n}\n\nclass ConflictsInput {\n  requisitos ConsolidatedRequirement[]\n  aspectos AspectClassification[]\n  tipos ExplanationTypeMapping[]\n  pares_candidatos RequirementPair[]\n  conflitos_existentes RequirementConflict[]\n}\n\nfunction AnalyzeConflicts(entrada: ConflictsInput, contexto: ContextItem[]) -> ConflictsArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 3.2.3 \"Analyze Conflicts\" do OpenUPExp: identificar conflitos entre\n    requisitos, stakeholders e objetivos de explicabilidade.\n\n    {{ RegrasNaoInvencao() }}\n\n    REGRAS ESPECÍFICAS\n    - Avalie TODOS os pares candidatos; devolva apenas os que têm conflito real.\n    - Exemplos de conflito: explicações simples × alto detalhamento; transparência × privacidade;\n      detalhamento × desempenho.\n    - Proponha alternativas de resolução sem decidir por elas.\n    - Mantenha o id de conflitos existentes que continuam válidos.\n\n    {{ _.role(\"user\") }}\n    REQUISITOS\n    {{ entrada.requisitos }}\n\n    ASPECTOS\n    {{ entrada.aspectos }}\n\n    TIPOS DE EXPLICAÇÃO\n    {{ entrada.tipos }}\n\n    PARES CANDIDATOS\n    {{ entrada.pares_candidatos }}\n\n    CONFLITOS EXISTENTES\n    {{ entrada.conflitos_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 3.2.4 Analyze Dependencies and Constraints — em lotes, com a base de referência\n// ---------------------------------------------------------------------------\n\nclass RequirementConstraint {\n  tipo ConstraintKind\n  descricao string\n  evidencias EvidenceRef[] @description(\"Trechos da base de referência (ex.: lei) que impõem a restrição\")\n}\n\nclass DependencyAnalysis {\n  id string? @description(\"DEP-n existente; null se novo\")\n  req_id string\n  depende_de string[] @description(\"REQ-n dos quais este depende (use o índice)\")\n  restricoes RequirementConstraint[]\n  impacto string? @description(\"Impacto das restrições sobre o requisito\")\n  lacunas Lacuna[]\n}\n\nclass DependenciesArtifact {\n  dependencias DependencyAnalysis[]\n}\n\nclass DependenciesInput {\n  requisitos ConsolidatedRequirement[]\n  caracterizacoes CharacterizedRequirement[]\n  indice RequirementIndexEntry[] @description(\"Todos os requisitos do projeto, para referência\")\n  dependencias_existentes DependencyAnalysis[]\n}\n\nfunction AnalyzeDependencies(entrada: DependenciesInput, contexto: ContextItem[]) -> DependenciesArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 3.2.4 \"Analyze Dependencies and Constraints\" do OpenUPExp: identificar\n    de quais outros requisitos cada requisito depende e quais restrições (regulatórias, éticas,\n    técnicas, organizacionais) o impactam.\n\n    {{ RegrasNaoInvencao() }}\n\n    REGRAS ESPECÍFICAS\n    - Exatamente uma análise por requisito da entrada.\n    - depende_de só com REQ-n do índice.\n    - Restrições regulatórias precisam de evidência recuperada (chunk_ref exato, citação literal);\n      sem evidência, registre Lacuna em vez de afirmar a restrição.\n    - Exemplo de registro: \"REQ-01 depende de rastreabilidade; impactado pela LGPD\".\n\n    {{ _.role(\"user\") }}\n    REQUISITOS\n    {{ entrada.requisitos }}\n\n    CARACTERIZAÇÕES\n    {{ entrada.caracterizacoes }}\n\n    ÍNDICE DE REQUISITOS\n    {{ entrada.indice }}\n\n    ANÁLISES EXISTENTES\n    {{ entrada.dependencias_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 3.2.5 Assess Feasibility — em lotes; matriz do passo 6\n// ---------------------------------------------------------------------------\n\nclass FeasibilityItem {\n  criterio FeasibilityCriterion\n  situacao FeasibilityStatus\n  observacao string?\n}\n\nclass FeasibilityAssessment {\n  id string? @description(\"FEA-n existente; null se novo\")\n  req_id string\n  criterios FeasibilityItem[] @description(\"Os quatro critérios: TECNICA, REGULATORIA, OPERACIONAL, ECONOMICA\")\n  riscos string[]\n  premissas string[]\n  lacunas Lacuna[]\n}\n\nclass FeasibilityArtifact {\n  avaliacoes FeasibilityAssessment[]\n}\n\nclass FeasibilityInput {\n  requisitos ConsolidatedRequirement[]\n  caracterizacoes CharacterizedRequirement[]\n  tipos ExplanationTypeMapping[]\n  dependencias DependencyAnalysis[]\n  conflitos RequirementConflict[]\n  avaliacoes_existentes FeasibilityAssessment[]\n}\n\nfunction AssessFeasibility(entrada: FeasibilityInput, contexto: ContextItem[]) -> FeasibilityArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 3.2.5 \"Assess Feasibility\" do OpenUPExp: avaliar se cada requisito pode\n    ser atendido considerando o sistema de IA, as restrições do projeto e o contexto de uso.\n\n    {{ RegrasNaoInvencao() }}\n\n    REGRAS ESPECÍFICAS\n    - Exatamente uma avaliação por requisito, com os quatro critérios (técnica, regulatória,\n      operacional, econômica).\n    - Use NAO_AVALIADO quando as entradas não permitirem concluir, com Lacuna. A avaliação final é\n      dos papéis Arquiteto de Software e Especialista em IA.\n    - Registre riscos e premissas que possam afetar a implementação.\n\n    {{ _.role(\"user\") }}\n    REQUISITOS\n    {{ entrada.requisitos }}\n\n    CARACTERIZAÇÕES\n    {{ entrada.caracterizacoes }}\n\n    TIPOS DE EXPLICAÇÃO\n    {{ entrada.tipos }}\n\n    DEPENDÊNCIAS E RESTRIÇÕES\n    {{ entrada.dependencias }}\n\n    CONFLITOS\n    {{ entrada.conflitos }}\n\n    AVALIAÇÕES EXISTENTES\n    {{ entrada.avaliacoes_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 3.2.6 Prioritize Requirements (MoSCoW) — visão global compacta (reduce)\n// ---------------------------------------------------------------------------\n\nclass RequirementAnalysisSummary {\n  id string\n  enunciado string\n  tipo string\n  aspecto_predominante string?\n  risco_decisao string?\n  viabilidade string @description(\"Resumo dos quatro critérios, ex.: TECNICA=SIM REGULATORIA=NAO_AVALIADO\")\n  conflitos string[] @description(\"CNF-n em que o requisito aparece\")\n  depende_de string[]\n}\n\nclass PriorityAssignment {\n  id string? @description(\"PRI-n existente; null se novo\")\n  req_id string\n  prioridade MoSCoW\n  justificativa string\n}\n\nclass PrioritiesArtifact {\n  prioridades PriorityAssignment[]\n}\n\nclass PrioritizeInput {\n  requisitos RequirementAnalysisSummary[]\n  prioridades_existentes PriorityAssignment[]\n}\n\nfunction PrioritizeRequirements(entrada: PrioritizeInput, contexto: ContextItem[]) -> PrioritiesArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 3.2.6 \"Prioritize Requirements\" do OpenUPExp: SUGERIR a prioridade MoSCoW\n    de cada requisito. A decisão final é humana, no consenso (A-16).\n\n    {{ RegrasNaoInvencao() }}\n\n    REGRAS ESPECÍFICAS\n    - Exatamente uma prioridade por requisito da entrada; nenhum pode ficar sem prioridade.\n    - Priorize depois de considerar conflitos, dependências e viabilidade.\n    - Justifique cada classificação; um requisito do qual outros dependem não deve ficar abaixo deles.\n    - Busque equilíbrio entre necessidades dos stakeholders, riscos e capacidade de implementação.\n\n    {{ _.role(\"user\") }}\n    REQUISITOS ANALISADOS (visão compacta)\n    {{ entrada.requisitos }}\n\n    PRIORIDADES EXISTENTES\n    {{ entrada.prioridades_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "clients.baml": "// Perfis nomeados por papel (docs/architecture/08-contratos-baml.md §8.5).\n// Experimentos sobrescrevem o cliente em tempo de execução (ClientRegistry),\n// sem fallback, para não trocar de modelo silenciosamente.\n\nretry_policy PadraoRetry {\n  max_retries 2\n  strategy {\n    type exponential_backoff\n    delay_ms 500\n    multiplier 2\n    max_delay_ms 8000\n  }\n}\n\nclient<llm> GroqGptOss120b {\n  provider openai-generic\n  retry_policy PadraoRetry\n  options {\n    base_url \"https://api.groq.com/openai/v1\"\n    api_key env.GROQ_API_KEY\n    model \"openai/gpt-oss-120b\"\n    temperature 0.0\n  }\n}\n\nclient<llm> GroqGptOss20b {\n  provider openai-generic\n  retry_policy PadraoRetry\n  options {\n    base_url \"https://api.groq.com/openai/v1\"\n    api_key env.GROQ_API_KEY\n    model \"openai/gpt-oss-20b\"\n    temperature 0.0\n  }\n}\n\nclient<llm> OpenAIGpt5Mini {\n  provider openai-responses\n  retry_policy PadraoRetry\n  options {\n    api_key env.OPENAI_API_KEY\n    model \"gpt-5-mini\"\n  }\n}\n\nclient<llm> AnthropicSonnet {\n  provider anthropic\n  retry_policy PadraoRetry\n  options {\n    api_key env.ANTHROPIC_API_KEY\n    model \"claude-sonnet-5-5\"\n    max_tokens 8192\n    temperature 0.0\n  }\n}\n\nclient<llm> GeminiFlash {\n  provider google-ai\n  retry_policy PadraoRetry\n  options {\n    api_key env.GEMINI_API_KEY\n    model \"gemini-2.5-flash\"\n    generationConfig { temperature 0.0 }\n  }\n}\n\n// Produção: fallback entre famílias diferentes de modelo.\nclient<llm> OpenUPExpDefault {\n  provider fallback\n  options {\n    strategy [GroqGptOss120b, OpenAIGpt5Mini, AnthropicSonnet]\n  }\n}\n\n// Tarefas simples (consultas, digests).\nclient<llm> OpenUPExpCheap {\n  provider fallback\n  options {\n    strategy [GroqGptOss20b, GeminiFlash]\n  }\n}\n",
    "common.baml": "// Tipos comuns (docs/architecture/08-contratos-baml.md §8.2)\n\nclass Lacuna {\n  campo string @description(\"Nome do campo que não pôde ser preenchido\")\n  motivo string @description(\"Por que a informação não está nas entradas\")\n  pergunta_sugerida string? @description(\"Pergunta que o Engenheiro de Requisitos pode fazer aos stakeholders\")\n}\n\nclass ContextItem {\n  origem string @description(\"required | digest | retrieved | related | feedback | document\")\n  referencia string @description(\"Referência estável do material\")\n  conteudo string\n}\n\nenum EvidenceKind {\n  OBRIGACAO_NORMATIVA @description(\"O trecho estabelece obrigação legal ou normativa aplicável ao contexto\")\n  RECOMENDACAO_TECNICA @description(\"O trecho recomenda, mas não obriga\")\n  DERIVADO_VISAO @description(\"O requisito decorre de uma necessidade da Visão; o trecho apenas contextualiza\")\n}\n\nclass EvidenceRef {\n  chunk_ref string @description(\"Exatamente o valor de referencia de um item de contexto com origem 'retrieved'\")\n  citacao string @description(\"Trecho LITERAL copiado do conteúdo desse item, sem reescrever\")\n  tipo EvidenceKind\n}\n\nclass OrigemRef {\n  referencia string @description(\"ID de item de entrada (ex.: STK-02, NEED-01) ou 'escopo'\")\n  relacao string @description(\"Como a saída decorre desta entrada\")\n}\n\ntemplate_string RegrasNaoInvencao() #\"\nREGRAS DE RIGOR (NÃO INVENÇÃO)\n1. Baseie-se EXCLUSIVAMENTE nas entradas fornecidas. Não use conhecimento externo.\n2. Não apresente inferências, hipóteses ou exemplos como fatos confirmados.\n3. Preserve exatamente os nomes, termos e domínios mencionados nas entradas.\n4. Quando uma informação não estiver nas entradas, deixe o campo vazio/nulo e registre\n   uma Lacuna explicando o motivo. Nunca complete lacunas por inferência.\n5. Não proponha técnicas, algoritmos, ferramentas ou arquiteturas que não estejam nas entradas.\n6. Não tome decisões que competem ao Engenheiro de Requisitos (prioridade, release,\n   aprovação) sem evidência explícita nas entradas.\n\"#\n\ntemplate_string RegrasIds(prefixo: string) #\"\nIDENTIFICADORES\n- Itens já existentes foram fornecidos com seus IDs ({{ prefixo }}-n). Se um item de saída\n  corresponde a um item existente, devolva o MESMO id.\n- Para itens novos, deixe o campo id como null; o sistema atribuirá o ID.\n\"#\n\ntemplate_string ContextoAdicional(contexto: ContextItem[]) #\"\n{% if contexto|length > 0 %}\nMATERIAL DE CONTEXTO ADICIONAL\n{% for c in contexto %}\n--- [{{ c.origem }}] {{ c.referencia }}{% if c.origem == \"feedback\" %}  <<< FEEDBACK DO REVISOR HUMANO: tem precedência; corrija a saída de acordo com ele, mantendo as regras de não invenção >>>{% endif %}\n{{ c.conteudo }}\n{% endfor %}\n{% endif %}\n\"#\n",
    "generators.baml": "generator target {\n  output_type \"python/pydantic\"\n  output_dir \"../openupexp\"\n  version \"0.226.2\"\n  default_client_mode \"async\"\n}\n",
    "requirements_2_1_prepare.baml": "// Subprocesso 2.1 Prepare Explainability Elicitation\n// O template do Plano de Elicitação ainda não existe na teoria (A-14). Os campos abaixo são\n// uma interpretação provisória derivada de tarefas/encontrar-descrever-requisitos.md (passo 1)\n// e da anotação BPMN \"Explainability Elicitation Strategy\".\n\n// Técnicas citadas no passo 1 de encontrar-descrever-requisitos.md\nenum ElicitationTechnique {\n  ENTREVISTA\n  WORKSHOP\n  OBSERVACAO @description(\"Observação de atividades\")\n  ANALISE_DOCUMENTAL\n  PROTOTIPO\n  OUTRA @description(\"Outra técnica adequada ao contexto; justifique no objetivo\")\n}\n\nclass ElicitationPlanItem {\n  id string? @description(\"EP-n existente; null se novo\")\n  stakeholder_id string @description(\"STK-n do stakeholder a ser ouvido\")\n  objetivo string @description(\"O que se quer compreender com este stakeholder sobre as decisões do sistema\")\n  tecnicas ElicitationTechnique[]\n  perguntas string[] @description(\"Roteiro de perguntas sobre necessidades de explicação (não sobre soluções)\")\n  need_ids string[] @description(\"Necessidades da Visão (NEED-n) que a elicitação deve aprofundar\")\n  lacunas_alvo string[] @description(\"Lacunas da Visão que esta elicitação tenta resolver (texto literal da lacuna)\")\n  lacunas Lacuna[]\n}\n\nclass ElicitationPlanArtifact {\n  itens ElicitationPlanItem[]\n}\n\nclass PlanElicitationInput {\n  stakeholders Stakeholder[]\n  necessidades ExplainabilityNeed[]\n  lacunas_visao string[] @description(\"Lacunas abertas da Visão aprovada\")\n  plano_existente ElicitationPlanItem[]\n}\n\nfunction PlanElicitation(entrada: PlanElicitationInput, contexto: ContextItem[]) -> ElicitationPlanArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 2.1.2 \"Explainability Elicitation Plan\" do OpenUPExp: planejar a\n    elicitação das necessidades de explicabilidade a partir da Visão aprovada.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"EP\") }}\n\n    REGRAS ESPECÍFICAS\n    - Exatamente um item de plano para cada stakeholder da entrada (use o STK-n em stakeholder_id).\n    - As perguntas investigam QUAIS decisões precisam ser explicadas, PARA QUEM, EM QUE CONTEXTO\n      e com qual OBJETIVO (compreensão, justificativa, auditoria, conformidade, confiança…).\n      Não pergunte sobre técnicas de explicação nem sobre soluções.\n    - Priorize perguntas que resolvam as lacunas da Visão; cite-as em lacunas_alvo.\n    - Escolha técnicas compatíveis com o stakeholder; o Engenheiro de Requisitos ajusta o plano.\n\n    {{ _.role(\"user\") }}\n    STAKEHOLDERS\n    {{ entrada.stakeholders }}\n\n    NECESSIDADES DE EXPLICABILIDADE DA VISÃO\n    {{ entrada.necessidades }}\n\n    LACUNAS ABERTAS DA VISÃO\n    {{ entrada.lacunas_visao }}\n\n    PLANO EXISTENTE (preserve os IDs)\n    {{ entrada.plano_existente }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "requirements_2_2_elicit.baml": "// Subprocesso 2.2 Elicit Explainability Requirements\n// Formatos provisórios (A-14): o template de requisito de explicabilidade ainda não existe na\n// teoria. Os objetivos de explicação vêm do passo 3 de tarefas/encontrar-descrever-requisitos.md.\n\n// Objetivos citados no passo 3 de encontrar-descrever-requisitos.md (lista provisória, A-15)\nenum ExplanationGoal {\n  COMPREENSAO\n  JUSTIFICATIVA\n  TRANSPARENCIA\n  RASTREABILIDADE\n  AUDITORIA\n  CONFORMIDADE_REGULATORIA\n  CONFIANCA\n  OUTRO @description(\"Outro objetivo; descreva no enunciado\")\n}\n\nclass ElicitationEvidence {\n  fonte_ref string @description(\"Exatamente a referencia de um item de contexto 'retrieved' (chunk:...) ou um SN-n da Visão\")\n  citacao string @description(\"Trecho LITERAL copiado da fonte, sem reescrever\")\n}\n\n// ---------------------------------------------------------------------------\n// 2.2.1 Obtain Explainability Needs — executada por stakeholder (map)\n// ---------------------------------------------------------------------------\n\nclass ElicitedNeed {\n  id string? @description(\"RN-n existente; null se nova\")\n  stakeholder_id string\n  necessidade string @description(\"Necessidade de explicação expressa pelo stakeholder, em suas palavras\")\n  decisao_alvo string? @description(\"Decisão, recomendação ou previsão do sistema que precisa ser explicada\")\n  objetivo ExplanationGoal?\n  need_ids string[] @description(\"NEED-n da Visão que esta necessidade aprofunda; vazio se for nova\")\n  evidencias ElicitationEvidence[] @description(\"Pelo menos uma; sem evidência, não produza a necessidade\")\n  lacunas Lacuna[]\n}\n\nclass ElicitedNeedsArtifact {\n  necessidades ElicitedNeed[]\n}\n\nclass ExtractNeedsInput {\n  stakeholder Stakeholder\n  plano ElicitationPlanItem?\n  solicitacoes_visao StakeholderNeed[] @description(\"Solicitações deste stakeholder registradas na Visão (1.1.3)\")\n  necessidades_visao ExplainabilityNeed[]\n  necessidades_existentes ElicitedNeed[]\n}\n\nfunction ExtractElicitedNeeds(entrada: ExtractNeedsInput, contexto: ContextItem[]) -> ElicitedNeedsArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 2.2.1 \"Obtain Explainability Needs\" do OpenUPExp para UM stakeholder:\n    extrair, do material de elicitação, as necessidades de explicação que ele expressou.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"RN\") }}\n\n    REGRAS ESPECÍFICAS\n    - Considere apenas o que este stakeholder disse ou o que o material atribui a ele.\n    - Cada necessidade precisa de evidência: copie a citação literal do trecho recuperado\n      (fonte_ref = referencia do item 'retrieved') ou da solicitação da Visão (fonte_ref = SN-n).\n    - Relacione a NEED-n da Visão quando a necessidade a aprofunda; necessidades novas ficam com\n      need_ids vazio e são igualmente importantes.\n    - Registre conflitos, dúvidas e expectativas divergentes como Lacuna.\n    - Se o material não trouxer nada sobre este stakeholder, retorne a lista vazia.\n\n    {{ _.role(\"user\") }}\n    STAKEHOLDER\n    {{ entrada.stakeholder }}\n\n    PLANO DE ELICITAÇÃO PARA ESTE STAKEHOLDER\n    {{ entrada.plano }}\n\n    SOLICITAÇÕES REGISTRADAS NA VISÃO\n    {{ entrada.solicitacoes_visao }}\n\n    NECESSIDADES DA VISÃO\n    {{ entrada.necessidades_visao }}\n\n    NECESSIDADES JÁ ELICITADAS (preserve os IDs)\n    {{ entrada.necessidades_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 2.2.2 Identify Explainability Requirements — executada por necessidade da Visão (map)\n// ---------------------------------------------------------------------------\n\nclass ExplainabilityRequirement {\n  id string? @description(\"RI-n existente; null se novo\")\n  enunciado string @description(\"O sistema deve ... (o QUÊ explicar, para QUEM, em que SITUAÇÃO; não o COMO)\")\n  stakeholder_ids string[]\n  need_ids string[] @description(\"NEED-n da Visão atendidas\")\n  rn_ids string[] @description(\"RN-n que sustentam o requisito (obrigatório)\")\n  objetivo ExplanationGoal\n  decisao_alvo string?\n  contexto_de_uso string?\n  lacunas Lacuna[]\n}\n\nclass ExplainabilityRequirementsArtifact {\n  requisitos ExplainabilityRequirement[]\n}\n\nclass IdentifyRequirementsInput {\n  necessidade ExplainabilityNeed? @description(\"Necessidade da Visão em foco; null para necessidades elicitadas novas\")\n  necessidades_elicitadas ElicitedNeed[] @description(\"RN-n a transformar em requisitos; TODAS devem ser usadas\")\n  stakeholders Stakeholder[]\n  glossario GlossaryTerm[]\n  requisitos_existentes ExplainabilityRequirement[]\n}\n\nfunction IdentifyExplainabilityRequirements(entrada: IdentifyRequirementsInput, contexto: ContextItem[]) -> ExplainabilityRequirementsArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 2.2.2 \"Identify Explainability Requirements\" do OpenUPExp: transformar\n    necessidades elicitadas em requisitos de explicabilidade em nível estratégico.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"RI\") }}\n\n    REGRAS ESPECÍFICAS\n    - Toda necessidade elicitada (RN-n) da entrada deve aparecer em rn_ids de pelo menos um requisito.\n    - O enunciado diz O QUE precisa ser explicado, PARA QUEM e EM QUE SITUAÇÃO. Conteúdo, formato,\n      mecanismos e níveis de explicação são detalhados em fases posteriores: não os defina aqui.\n    - Use os termos do glossário.\n    - Requisitos de stakeholders diferentes com objetivos diferentes ficam separados.\n\n    {{ _.role(\"user\") }}\n    NECESSIDADE DA VISÃO EM FOCO\n    {{ entrada.necessidade }}\n\n    NECESSIDADES ELICITADAS\n    {{ entrada.necessidades_elicitadas }}\n\n    STAKEHOLDERS\n    {{ entrada.stakeholders }}\n\n    GLOSSÁRIO\n    {{ entrada.glossario }}\n\n    REQUISITOS EXISTENTES (preserve os IDs)\n    {{ entrada.requisitos_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 2.2.3 Identify Complementary Requirements — refina os CR-n da Visão (interpretação de A-18)\n// ---------------------------------------------------------------------------\n\nclass PhaseComplementaryRequirement {\n  id string? @description(\"RC-n existente; null se novo\")\n  categoria ComplementaryCategory\n  requisito string\n  justificativa string\n  ri_ids string[] @description(\"Requisitos de explicabilidade (RI-n) afetados (obrigatório)\")\n  cr_ids string[] @description(\"CR-n da Visão que este requisito refina; vazio se novo\")\n  evidencias EvidenceRef[] @description(\"Pelo menos uma; sem evidência, não produza o requisito\")\n}\n\nclass PhaseComplementaryArtifact {\n  requisitos PhaseComplementaryRequirement[]\n}\n\nclass RefineComplementaryInput {\n  requisitos ExplainabilityRequirement[]\n  requisitos_complementares_visao ComplementaryRequirement[]\n  requisitos_existentes PhaseComplementaryRequirement[]\n}\n\nfunction RefineComplementaryRequirements(entrada: RefineComplementaryInput, contexto: ContextItem[]) -> PhaseComplementaryArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 2.2.3 \"Identify Complementary Requirements\" do OpenUPExp: identificar\n    restrições, dependências e requisitos complementares (normas, desempenho, privacidade,\n    auditoria, documentação) que influenciam os requisitos de explicabilidade elicitados.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"RC\") }}\n\n    REGRAS ESPECÍFICAS\n    - Parta dos requisitos complementares da Visão (CR-n): refine-os à luz dos requisitos\n      elicitados (RI-n) e registre o CR-n refinado em cr_ids.\n    - Requisitos novos só com evidência na base de referência recuperada.\n    - Cada requisito aponta os RI-n afetados.\n    - Evidência: chunk_ref = referencia exata de um item 'retrieved'; citacao = trecho literal.\n\n    {{ _.role(\"user\") }}\n    REQUISITOS DE EXPLICABILIDADE ELICITADOS\n    {{ entrada.requisitos }}\n\n    REQUISITOS COMPLEMENTARES DA VISÃO\n    {{ entrada.requisitos_complementares_visao }}\n\n    REQUISITOS EXISTENTES (preserve os IDs)\n    {{ entrada.requisitos_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 2.2.4 Organize and Consolidate Requirements\n// ---------------------------------------------------------------------------\n\nenum RequirementKind {\n  EXPLICABILIDADE\n  COMPLEMENTAR\n}\n\nclass ConsolidatedRequirement {\n  id string? @description(\"REQ-n existente; null se novo\")\n  enunciado string\n  tipo RequirementKind\n  objetivo ExplanationGoal?\n  categoria ComplementaryCategory? @description(\"Somente para tipo COMPLEMENTAR\")\n  stakeholder_ids string[]\n  need_ids string[]\n  origem_ids string[] @description(\"RI-n e RC-n consolidados neste requisito (obrigatório)\")\n  justificativa_agrupamento string? @description(\"Por que itens foram fundidos; null se não houve fusão\")\n  lacunas Lacuna[]\n}\n\nclass DiscardedItem {\n  origem_id string @description(\"RI-n ou RC-n não incorporado\")\n  motivo string @description(\"Ex.: duplicado de REQ-n, fora do escopo da Visão\")\n}\n\nclass ConsolidatedRequirementsArtifact {\n  requisitos ConsolidatedRequirement[]\n  descartados DiscardedItem[]\n}\n\nclass SimilarPair {\n  a string\n  b string\n  similaridade float\n}\n\nclass ConsolidateInput {\n  requisitos ExplainabilityRequirement[]\n  complementares PhaseComplementaryRequirement[]\n  pares_similares SimilarPair[] @description(\"Candidatos a duplicidade calculados por similaridade semântica\")\n  consolidados_existentes ConsolidatedRequirement[]\n}\n\nfunction ConsolidateRequirements(entrada: ConsolidateInput, contexto: ContextItem[]) -> ConsolidatedRequirementsArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 2.2.4 \"Organize and Consolidate Requirements\" do OpenUPExp: organizar\n    os requisitos elicitados e complementares num conjunto consolidado, sem perder nenhum.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"REQ\") }}\n\n    REGRAS ESPECÍFICAS\n    - TODO RI-n e RC-n da entrada aparece em origem_ids de um requisito consolidado OU em descartados.\n    - Funda apenas itens realmente equivalentes (os pares_similares são candidatos, não certezas);\n      explique a fusão em justificativa_agrupamento.\n    - Ao fundir, preserve a união de stakeholders, necessidades e objetivos.\n    - Descarte só com motivo explícito (duplicidade ou fora do escopo da Visão).\n    - Não reescreva o sentido dos requisitos; padronize apenas a redação (\"O sistema deve...\").\n\n    {{ _.role(\"user\") }}\n    REQUISITOS DE EXPLICABILIDADE (RI)\n    {{ entrada.requisitos }}\n\n    REQUISITOS COMPLEMENTARES (RC)\n    {{ entrada.complementares }}\n\n    CANDIDATOS A DUPLICIDADE\n    {{ entrada.pares_similares }}\n\n    CONSOLIDADOS EXISTENTES (preserve os IDs)\n    {{ entrada.consolidados_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "specification_4_specify.baml": "// Fase 4 — Define Explainability Specification\n// Passos de OpenUPExp/tarefas/especificar-requisitos.md (1–4). A teoria não traz template para\n// HU, critérios de aceitação e características da explicação (o DRE só tem a Visão e o\n// Glossário); os formatos abaixo seguem os \"formatos recomendados\" e as listas dos passos\n// (provisório, A-14/A-21), ver docs/architecture/12-decisoes-pendentes.md §12.6.\n\n// ---------------------------------------------------------------------------\n// Características da explicação (passo 3; momento e forma também no checklist de limites)\n// ---------------------------------------------------------------------------\n\nenum ExplanationDetailLevel {\n  RESUMIDO\n  INTERMEDIARIO\n  DETALHADO\n}\n\nenum ExplanationFormat {\n  TEXTUAL\n  VISUAL\n  TABULAR\n  COMBINADO\n}\n\nenum ExplanationMoment {\n  ANTES @description(\"Antes da decisão\")\n  DURANTE @description(\"Durante a decisão\")\n  APOS @description(\"Após a decisão\")\n  SOB_DEMANDA @description(\"Quando solicitada pelo stakeholder\")\n}\n\n// Ficha de entrada por requisito, montada deterministicamente em 4.1.2 a partir da Análise.\nclass SpecificationPlanEntry {\n  req_id string\n  enunciado string\n  prioridade string? @description(\"MoSCoW aprovado na Fase 3\")\n  stakeholder_ids string[]\n  need_ids string[]\n  aspecto_predominante string?\n  tipos_explicacao string[]\n  contexto_uso string?\n  decisao_apoiada string?\n  objetivo_principal string?\n  restricoes string[] @description(\"Restrições da Fase 3 (tipo: descrição)\")\n}\n\n// ---------------------------------------------------------------------------\n// 4.2.1 Specify Requirements — Histórias de Usuário, em lotes de requisitos\n// ---------------------------------------------------------------------------\n\nclass UserStory {\n  id string? @description(\"HU-n existente; null se nova\")\n  req_id string @description(\"REQ-n especificado pela história\")\n  stakeholder_id string @description(\"STK-n do 'Como'\")\n  como string @description(\"Nome do stakeholder, como está na entrada\")\n  quero string @description(\"Necessidade de explicabilidade, sem detalhes de implementação\")\n  para string @description(\"Benefício esperado\")\n  lacunas Lacuna[]\n}\n\nclass UserStoriesArtifact {\n  historias UserStory[]\n}\n\nclass SpecifyStoriesInput {\n  requisitos SpecificationPlanEntry[]\n  stakeholders Stakeholder[]\n  historias_existentes UserStory[]\n}\n\nfunction SpecifyUserStories(entrada: SpecifyStoriesInput, contexto: ContextItem[]) -> UserStoriesArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 4.2.1 \"Specify Requirements\" do OpenUPExp: especificar cada requisito de\n    explicabilidade como História de Usuário (HU), sob a perspectiva do stakeholder.\n\n    {{ RegrasNaoInvencao() }}\n\n    {{ RegrasIds(\"HU\") }}\n\n    REGRAS ESPECÍFICAS\n    - Formato: Como <stakeholder> / Quero <necessidade de explicabilidade> / Para <benefício esperado>.\n    - Pelo menos uma HU por requisito da entrada (req_id = REQ-n). Uma HU expressa UMA necessidade\n      principal; se o requisito atende stakeholders com necessidades distintas, escreva uma HU por\n      stakeholder (stakeholder_id entre os stakeholder_ids do requisito).\n    - Linguagem simples, orientada ao valor; NÃO inclua técnica de explicabilidade, algoritmo ou tela.\n    - O benefício (\"para\") deve decorrer do objetivo e da decisão apoiada da ficha; sem base, registre Lacuna.\n\n    {{ _.role(\"user\") }}\n    REQUISITOS (fichas da Análise aprovada)\n    {{ entrada.requisitos }}\n\n    STAKEHOLDERS\n    {{ entrada.stakeholders }}\n\n    HISTÓRIAS EXISTENTES\n    {{ entrada.historias_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 4.2.2 Define Acceptance Criteria — Dado/Quando/Então, em lotes de HU\n// ---------------------------------------------------------------------------\n\nclass AcceptanceScenario {\n  dado string @description(\"Contexto/pré-condição\")\n  quando string @description(\"Evento ou ação\")\n  entao string @description(\"Resultado observável e verificável\")\n}\n\nclass AcceptanceCriteria {\n  id string? @description(\"CA-n existente; null se novo\")\n  hu_id string @description(\"HU-n a que os cenários se aplicam\")\n  cenarios AcceptanceScenario[]\n  lacunas Lacuna[]\n}\n\nclass AcceptanceCriteriaArtifact {\n  criterios AcceptanceCriteria[]\n}\n\nclass AcceptanceInput {\n  historias UserStory[]\n  requisitos SpecificationPlanEntry[]\n  criterios_existentes AcceptanceCriteria[]\n}\n\nfunction DefineAcceptanceCriteria(entrada: AcceptanceInput, contexto: ContextItem[]) -> AcceptanceCriteriaArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 4.2.2 \"Define Acceptance Criteria\" do OpenUPExp: definir critérios de\n    aceitação objetivos para cada História de Usuário de explicabilidade.\n\n    {{ RegrasNaoInvencao() }}\n\n    REGRAS ESPECÍFICAS\n    - Exatamente um conjunto de critérios por HU da entrada (hu_id = HU-n), com um ou mais cenários\n      no formato Dado / Quando / Então.\n    - O \"Então\" descreve comportamento observável e verificável; evite termos vagos (\"adequado\",\n      \"rápido\", \"fácil\", \"claro\") sem condição mensurável.\n    - Critérios independentes de tecnologia, coerentes com o objetivo e as restrições da ficha.\n    - Valores mensuráveis (tempos, quantidades) só se estiverem nas entradas; senão, registre Lacuna\n      com a pergunta para os stakeholders.\n    - Mantenha o id dos critérios existentes da mesma HU.\n\n    {{ _.role(\"user\") }}\n    HISTÓRIAS DE USUÁRIO\n    {{ entrada.historias }}\n\n    FICHAS DOS REQUISITOS\n    {{ entrada.requisitos }}\n\n    CRITÉRIOS EXISTENTES\n    {{ entrada.criterios_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 4.2.3 Specify Explanation Characteristics — em lotes de HU\n// ---------------------------------------------------------------------------\n\nclass ExplanationCharacteristics {\n  id string? @description(\"CEX-n existente; null se novo\")\n  hu_id string\n  objetivo string? @description(\"Objetivo da explicação\")\n  publico_alvo string[] @description(\"STK-n que recebem a explicação\")\n  contexto_utilizacao string?\n  nivel_detalhamento ExplanationDetailLevel?\n  formato ExplanationFormat?\n  momento ExplanationMoment?\n  requisitos_qualidade string[] @description(\"Requisitos de qualidade da explicação presentes nas entradas\")\n  lacunas Lacuna[]\n}\n\nclass ExplanationCharacteristicsArtifact {\n  caracteristicas ExplanationCharacteristics[]\n}\n\nclass CharacteristicsInput {\n  historias UserStory[]\n  requisitos SpecificationPlanEntry[]\n  criterios AcceptanceCriteria[]\n  limites_visao LimitAnswer[] @description(\"Respostas do checklist de limites da Visão (forma, momento, etc.)\")\n  caracteristicas_existentes ExplanationCharacteristics[]\n}\n\nfunction SpecifyExplanationCharacteristics(entrada: CharacteristicsInput, contexto: ContextItem[]) -> ExplanationCharacteristicsArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 4.2.3 \"Specify Explanation Characteristics\" do OpenUPExp: descrever as\n    características esperadas da explicação associada a cada História de Usuário.\n\n    {{ RegrasNaoInvencao() }}\n\n    REGRAS ESPECÍFICAS\n    - Exatamente um registro por HU da entrada (hu_id = HU-n).\n    - Características: objetivo, público-alvo, contexto de utilização, nível de detalhamento,\n      formato de apresentação, momento em que a explicação é disponibilizada e requisitos de qualidade.\n    - Use as respostas do checklist de limites da Visão quando tratarem de forma ou momento.\n    - NÃO especifique algoritmos, técnicas de explicabilidade ou componentes de interface.\n    - Campo sem evidência fica null e gera Lacuna com pergunta sugerida.\n\n    {{ _.role(\"user\") }}\n    HISTÓRIAS DE USUÁRIO\n    {{ entrada.historias }}\n\n    FICHAS DOS REQUISITOS\n    {{ entrada.requisitos }}\n\n    CRITÉRIOS DE ACEITAÇÃO\n    {{ entrada.criterios }}\n\n    LIMITES DA EXPLICABILIDADE (Visão)\n    {{ entrada.limites_visao }}\n\n    CARACTERÍSTICAS EXISTENTES\n    {{ entrada.caracteristicas_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 4.2.4 Establish Traceability — determinística (sem LLM); classe só para o schema\n// ---------------------------------------------------------------------------\n\nclass TraceabilityRow {\n  id string?\n  hu string\n  req string\n  rer string?\n  stakeholder string\n  necessidades string[]\n  origens string[] @description(\"RI-n/RC-n da Fase 2 consolidados no requisito\")\n  ca string?\n  cex string?\n  prioridade string?\n}\n\nclass TraceabilityMatrix {\n  linhas TraceabilityRow[]\n}\n",
    "vision_1_1_prepare.baml": "// Subprocesso 1.1 Prepare Explainability Vision\n// Contratos derivados dos workers W1/W3 originais (legado), estendidos com IDs,\n// origem e lacunas estruturadas.\n\n// ---------------------------------------------------------------------------\n// 1.1.1 Define Explainability Problem  (evolução do W1 AnalyzeExplainabilityScope)\n// ---------------------------------------------------------------------------\n\nclass ProblemStatement {\n  o_problema_da string @description(\"Template §2.1 — 'O problema da'\")\n  afeta string[] @description(\"Template §2.1 — 'afeta' (nomes literais da entrada)\")\n  cujo_impacto_e string[] @description(\"Template §2.1 — 'cujo o impacto é'\")\n  solucao_bem_sucedida string? @description(\"Template §2.1 — 'uma solução bem sucedida seria'\")\n}\n\nclass ExplainabilityProblem {\n  necessidade_de_explicabilidade string\n  descricao_geral string\n  dominio_do_problema string\n  stakeholders_mencionados string[] @description(\"Nomes literais de stakeholders citados na entrada\")\n  impactos string[]\n  criterios_de_sucesso string?\n  declaracao_problema ProblemStatement\n  lacunas Lacuna[]\n}\n\nclass DefineProblemInput {\n  documento_escopo string\n}\n\nfunction DefineExplainabilityProblem(entrada: DefineProblemInput, contexto: ContextItem[]) -> ExplainabilityProblem {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você é um especialista em Engenharia de Requisitos para sistemas de IA, executando a tarefa\n    1.1.1 \"Define Explainability Problem\" do processo OpenUPExp (Visão da Explicabilidade).\n\n    OBJETIVO\n    Identificar por que e em qual contexto o sistema inteligente precisa fornecer explicações\n    sobre suas decisões ou comportamentos, e redigir a Declaração do Problema.\n\n    {{ RegrasNaoInvencao() }}\n\n    REGRAS ESPECÍFICAS\n    - Descreva a necessidade de transparência sem presumir técnicas de XAI.\n    - 'impactos': lista vazia se não houver impactos descritos.\n    - 'declaracao_problema': preencha somente com o que a entrada sustenta.\n\n    {{ _.role(\"user\") }}\n    DOCUMENTO DE ESCOPO DO PROJETO\n    {{ entrada.documento_escopo }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 1.1.2 Identify Stakeholders  (absorve o W3 DescribeStakeholders)\n// ---------------------------------------------------------------------------\n\nclass Stakeholder {\n  id string? @description(\"STK-n de um stakeholder existente; null se for novo\")\n  nome string\n  descricao string\n  responsabilidade string? @description(\"Somente responsabilidade explicitamente sustentada pela entrada\")\n  ambiente_usuario string? @description(\"Template §3.2 — contexto de uso, plataformas, restrições, se houver evidência\")\n  origem OrigemRef[]\n  lacunas Lacuna[]\n}\n\nclass StakeholdersArtifact {\n  stakeholders Stakeholder[]\n}\n\nclass IdentifyStakeholdersInput {\n  problema ExplainabilityProblem\n  documento_escopo string\n  stakeholders_existentes Stakeholder[]\n}\n\nfunction IdentifyStakeholders(entrada: IdentifyStakeholdersInput, contexto: ContextItem[]) -> StakeholdersArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 1.1.2 \"Identify Stakeholders\" do OpenUPExp: identificar quem precisa\n    compreender, auditar, validar ou contestar as decisões do sistema de IA.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"STK\") }}\n\n    REGRAS ESPECÍFICAS\n    - Considere os stakeholders mencionados no problema e no escopo. Não agrupe nem substitua.\n    - 'descricao': relação do stakeholder com o sistema e com a explicabilidade, conforme a entrada.\n    - 'responsabilidade': benefícios desejados ou objetivos do produto NÃO são responsabilidades.\n      Sem evidência, deixe null e registre uma Lacuna.\n    - 'origem': indique de onde veio cada stakeholder ('escopo' ou o campo do problema).\n\n    {{ _.role(\"user\") }}\n    PROBLEMA DE EXPLICABILIDADE (1.1.1)\n    {{ entrada.problema }}\n\n    DOCUMENTO DE ESCOPO\n    {{ entrada.documento_escopo }}\n\n    STAKEHOLDERS EXISTENTES (preserve os IDs)\n    {{ entrada.stakeholders_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 1.1.3 Identify Stakeholder Needs  — interpretação de trabalho (A-04):\n// solicitações brutas, nas palavras da fonte, com origem rastreável.\n// ---------------------------------------------------------------------------\n\nclass StakeholderNeed {\n  id string? @description(\"SN-n existente; null se nova\")\n  stakeholder_id string @description(\"ID STK-n do stakeholder\")\n  solicitacao string @description(\"Nas palavras da fonte, sem reinterpretação\")\n  origem OrigemRef[]\n}\n\nclass StakeholderNeedsArtifact {\n  solicitacoes StakeholderNeed[]\n}\n\nclass IdentifyStakeholderNeedsInput {\n  stakeholders Stakeholder[]\n  documento_escopo string\n  solicitacoes_existentes StakeholderNeed[]\n}\n\nfunction IdentifyStakeholderNeeds(entrada: IdentifyStakeholderNeedsInput, contexto: ContextItem[]) -> StakeholderNeedsArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 1.1.3 \"Identify Stakeholder Needs\" do OpenUPExp: registrar as\n    solicitações de cada stakeholder relacionadas à compreensão das decisões do sistema,\n    nas palavras da fonte, sem transformá-las ainda em requisitos ou necessidades conceituais.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"SN\") }}\n\n    REGRAS ESPECÍFICAS\n    - Use o ID STK-n exato de cada stakeholder em 'stakeholder_id'.\n    - Não crie solicitações só para que todo stakeholder tenha uma.\n    - 'origem' deve apontar o trecho ou campo de onde a solicitação foi extraída.\n\n    {{ _.role(\"user\") }}\n    STAKEHOLDERS\n    {{ entrada.stakeholders }}\n\n    DOCUMENTO DE ESCOPO\n    {{ entrada.documento_escopo }}\n\n    SOLICITAÇÕES EXISTENTES (preserve os IDs)\n    {{ entrada.solicitacoes_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 1.1.4 Capture Domain Terminology / 1.1.5 Create Initial Glossary\n// ---------------------------------------------------------------------------\n\nclass DomainTerm {\n  id string? @description(\"DT-n existente; null se novo\")\n  termo string\n  contexto_de_uso string @description(\"Frase ou trecho da entrada em que o termo aparece\")\n}\n\nclass DomainTermsArtifact {\n  termos DomainTerm[]\n}\n\nclass CaptureTermsInput {\n  documento_escopo string\n  problema ExplainabilityProblem\n}\n\nfunction CaptureDomainTerminology(entrada: CaptureTermsInput, contexto: ContextItem[]) -> DomainTermsArtifact {\n  client OpenUPExpCheap\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 1.1.4 \"Capture Domain Terminology\" do OpenUPExp: capturar termos do\n    domínio e de explicabilidade que precisam de entendimento comum entre stakeholders e equipe.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"DT\") }}\n\n    REGRAS ESPECÍFICAS\n    - Capture apenas termos que aparecem nas entradas; 'contexto_de_uso' deve ser literal.\n    - Priorize termos técnicos, siglas, papéis e conceitos com risco de ambiguidade.\n\n    {{ _.role(\"user\") }}\n    DOCUMENTO DE ESCOPO\n    {{ entrada.documento_escopo }}\n\n    PROBLEMA DE EXPLICABILIDADE\n    {{ entrada.problema }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\nclass GlossaryTerm {\n  id string? @description(\"TERM-n existente; null se novo\")\n  termo string\n  definicao string? @description(\"Definição sustentada pela entrada; null se a entrada não define\")\n  sinonimos string[]\n  termo_origem_id string? @description(\"ID DT-n do termo capturado\")\n  lacunas Lacuna[]\n}\n\nclass GlossaryArtifact {\n  termos GlossaryTerm[]\n}\n\nclass CreateGlossaryInput {\n  termos DomainTerm[]\n  glossario_existente GlossaryTerm[]\n}\n\nfunction CreateInitialGlossary(entrada: CreateGlossaryInput, contexto: ContextItem[]) -> GlossaryArtifact {\n  client OpenUPExpCheap\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 1.1.5 \"Create Initial Glossary\" do OpenUPExp.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"TERM\") }}\n\n    REGRAS ESPECÍFICAS\n    - Uma entrada de glossário por termo capturado relevante; consolide sinônimos.\n    - 'definicao' apenas quando o contexto de uso a sustenta; caso contrário null + Lacuna\n      com uma pergunta sugerida para os stakeholders.\n\n    {{ _.role(\"user\") }}\n    TERMOS CAPTURADOS (1.1.4)\n    {{ entrada.termos }}\n\n    GLOSSÁRIO EXISTENTE (preserve os IDs)\n    {{ entrada.glossario_existente }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "vision_1_2_develop.baml": "// Subprocesso 1.2 Develop Explainability Vision\n// Contratos derivados dos workers W2/W4/W5/W6 originais (legado).\n\n// ---------------------------------------------------------------------------\n// 1.2.1 Identify Explainability Needs  (evolução do W4 MapExplainabilityNeeds)\n// ---------------------------------------------------------------------------\n\nclass ExplainabilityNeed {\n  id string? @description(\"NEED-n existente; null se nova\")\n  necessidade string @description(\"Necessidade de explicabilidade em nível conceitual (o quê e por quê, não o como)\")\n  stakeholder_ids string[] @description(\"IDs STK-n relacionados\")\n  solicitacao_ids string[] @description(\"IDs SN-n que sustentam a necessidade\")\n  prioridade string? @description(\"Somente se explicitamente indicada na entrada; caso contrário null\")\n  planned_release string? @description(\"Somente se explicitamente indicada na entrada; caso contrário null\")\n  aspecto_associado string? @description(\"Opcional (decisão A-06 pendente); somente se a entrada sustentar\")\n  lacunas Lacuna[]\n}\n\nclass ExplainabilityNeedsArtifact {\n  necessidades ExplainabilityNeed[]\n}\n\nclass IdentifyNeedsInput {\n  stakeholders Stakeholder[]\n  solicitacoes StakeholderNeed[]\n  glossario GlossaryTerm[]\n  necessidades_existentes ExplainabilityNeed[]\n}\n\nfunction IdentifyExplainabilityNeeds(entrada: IdentifyNeedsInput, contexto: ContextItem[]) -> ExplainabilityNeedsArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 1.2.1 \"Identify Explainability Needs\" do OpenUPExp: transformar as\n    solicitações dos stakeholders em necessidades de explicabilidade em nível conceitual.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"NEED\") }}\n\n    REGRAS ESPECÍFICAS\n    - Cada necessidade deve citar os SN-n que a sustentam e os STK-n envolvidos.\n    - Agrupe solicitações equivalentes somente sem perder distinções relevantes.\n    - Não transforme necessidades em funcionalidades, mecanismos, algoritmos ou métricas.\n    - Prioridade e release: null quando não houver evidência explícita (registre Lacuna).\n    - Se não houver evidência suficiente, retorne a lista vazia.\n\n    {{ _.role(\"user\") }}\n    STAKEHOLDERS\n    {{ entrada.stakeholders }}\n\n    SOLICITAÇÕES DOS STAKEHOLDERS (1.1.3)\n    {{ entrada.solicitacoes }}\n\n    GLOSSÁRIO\n    {{ entrada.glossario }}\n\n    NECESSIDADES EXISTENTES (preserve os IDs)\n    {{ entrada.necessidades_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// Posicionamento (template §2.2) — sem tarefa BPMN (A-03)\n// Evolução do W2 GenerateExplainabilityPositioning\n// ---------------------------------------------------------------------------\n\nclass Positioning {\n  id string? @description(\"POS-n existente; null se novo\")\n  stakeholder_id string\n  para_quem string\n  para_que string\n  nome_produto string?\n  categoria_produto string?\n  beneficio_chave string?\n  unlike string? @description(\"Alternativa de referência; null se não estiver na entrada\")\n  our_product string?\n  need_ids string[]\n  lacunas Lacuna[]\n}\n\nclass PositioningArtifact {\n  posicionamentos Positioning[]\n}\n\nclass PositioningInput {\n  problema ExplainabilityProblem\n  stakeholders Stakeholder[]\n  necessidades ExplainabilityNeed[]\n  posicionamentos_existentes Positioning[]\n}\n\nfunction GenerateExplainabilityPositioning(entrada: PositioningInput, contexto: ContextItem[]) -> PositioningArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você elabora a Declaração de Posicionamento da Explicabilidade (template da Visão §2.2) do\n    OpenUPExp, uma por perfil de stakeholder que necessita de explicabilidade.\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"POS\") }}\n\n    REGRAS ESPECÍFICAS\n    - Exatamente um posicionamento para cada stakeholder da entrada (use o STK-n em stakeholder_id).\n    - Relacione as necessidades (NEED-n) que justificam o posicionamento.\n    - Campos sem evidência (ex.: unlike, beneficio_chave): null + Lacuna para o Engenheiro.\n\n    {{ _.role(\"user\") }}\n    PROBLEMA\n    {{ entrada.problema }}\n\n    STAKEHOLDERS\n    {{ entrada.stakeholders }}\n\n    NECESSIDADES DE EXPLICABILIDADE\n    {{ entrada.necessidades }}\n\n    POSICIONAMENTOS EXISTENTES (preserve os IDs)\n    {{ entrada.posicionamentos_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 1.2.2 Identify Complementary Requirements\n//   PlanReferenceQueries (evolução do W5) + recuperação híbrida (determinística)\n//   + DevelopComplementaryRequirements (evolução do W6, com evidência tipada — P-03)\n// ---------------------------------------------------------------------------\n\nenum ComplementaryCategory {\n  NORMAS_REGULAMENTOS @description(\"§5.1 Padrões, Normas e Regulamentos Aplicáveis\")\n  PLATAFORMA_DESEMPENHO @description(\"§5.2 Plataforma, Hardware e Desempenho\")\n  QUALIDADE_EXPLICACOES @description(\"§5.3 Qualidade das Explicações\")\n  RESTRICOES_DEPENDENCIAS @description(\"§5.4 Restrições de Design, Dependências e Assunções\")\n  DOCUMENTACAO_SUPORTE @description(\"§5.5 Documentação e Suporte\")\n}\n\nclass ReferenceQuery {\n  secao ComplementaryCategory\n  consulta string @description(\"Consulta curta e objetiva para recuperação\")\n  tipos_fonte string[] @description(\"Subconjunto de: lei, manual, academico\")\n  referencias_explicitas string[] @description(\"Referências normativas citadas na entrada, ex.: 'Lei 13.709 art. 20'\")\n}\n\nclass ReferenceQueryPlan {\n  consultas ReferenceQuery[]\n}\n\nclass PlanQueriesInput {\n  problema ExplainabilityProblem\n  necessidades ExplainabilityNeed[]\n}\n\nfunction PlanReferenceQueries(entrada: PlanQueriesInput, contexto: ContextItem[]) -> ReferenceQueryPlan {\n  client OpenUPExpCheap\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você planeja consultas à Explainability Reference Base (normas, leis, manuais, literatura)\n    para a seção 5 — Requisitos Adicionais relacionados à Explicabilidade — do Documento de Visão.\n\n    REGRAS\n    - Gere de 3 a 8 consultas curtas, cada uma focada numa subseção (5.1 a 5.5) pertinente.\n    - Use o domínio e as necessidades das entradas; não invente normas.\n    - 'referencias_explicitas' só pode conter referências normativas que aparecem literalmente\n      nas entradas. Caso contrário, lista vazia.\n    - Não defina prioridades nem releases.\n\n    {{ _.role(\"user\") }}\n    PROBLEMA\n    {{ entrada.problema }}\n\n    NECESSIDADES DE EXPLICABILIDADE\n    {{ entrada.necessidades }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\nclass ComplementaryRequirement {\n  id string? @description(\"CR-n existente; null se novo\")\n  categoria ComplementaryCategory\n  requisito string\n  justificativa string @description(\"Relação entre a necessidade da Visão e a evidência\")\n  need_ids string[] @description(\"Necessidades da Visão relacionadas (obrigatório)\")\n  evidencias EvidenceRef[] @description(\"Pelo menos uma; sem evidência, não produza o requisito\")\n}\n\nclass ComplementaryRequirementsArtifact {\n  requisitos ComplementaryRequirement[]\n}\n\nclass ComplementaryInput {\n  problema ExplainabilityProblem\n  necessidades ExplainabilityNeed[]\n  requisitos_existentes ComplementaryRequirement[]\n}\n\nfunction DevelopComplementaryRequirements(entrada: ComplementaryInput, contexto: ContextItem[]) -> ComplementaryRequirementsArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 1.2.2 \"Identify Complementary Requirements\" do OpenUPExp: elaborar\n    requisitos adicionais relacionados à explicabilidade (Visão §5.1–5.5), fundamentados\n    nos trechos da Explainability Reference Base fornecidos no contexto (origem 'retrieved').\n\n    {{ RegrasNaoInvencao() }}\n    {{ RegrasIds(\"CR\") }}\n\n    VALIDAÇÃO OBRIGATÓRIA DAS EVIDÊNCIAS\n    1. Cada requisito deve ser complementar a pelo menos uma necessidade (need_ids).\n    2. Antes de elaborar um requisito, identifique o trecho exato que o sustenta. Em\n       'evidencias', use a 'referencia' do item de contexto e copie a 'citacao' LITERALMENTE.\n       Citações são verificadas mecanicamente contra o texto da fonte.\n    3. Verifique se o trecho se aplica ao domínio e à situação. Não generalize uma obrigação\n       prevista para um contexto específico.\n    4. Diferencie o tipo: OBRIGACAO_NORMATIVA, RECOMENDACAO_TECNICA ou DERIVADO_VISAO.\n    5. Não afirme que uma lei exige uma funcionalidade se o trecho não estabelece essa obrigação.\n    6. Não infira requisitos apenas da existência de uma autoridade reguladora ou de\n       princípios gerais.\n    7. Não detalhe implementação, não atribua prioridade nem release.\n    8. Não crie requisitos apenas para preencher categorias. Sem evidência suficiente,\n       descarte o requisito. Retorne lista vazia se nenhum for fundamentado.\n\n    {{ _.role(\"user\") }}\n    PROBLEMA\n    {{ entrada.problema }}\n\n    NECESSIDADES DE EXPLICABILIDADE\n    {{ entrada.necessidades }}\n\n    REQUISITOS COMPLEMENTARES EXISTENTES (preserve os IDs)\n    {{ entrada.requisitos_existentes }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n\n// ---------------------------------------------------------------------------\n// 1.2.3 Define Explainability Scope and Limits (checklist do DRE)\n// ---------------------------------------------------------------------------\n\nclass ChecklistQuestion {\n  dimensao string\n  pergunta string\n}\n\nclass LimitAnswer {\n  dimensao string\n  pergunta string @description(\"Pergunta do checklist, literal\")\n  resposta string? @description(\"Resposta sustentada pelas entradas; null se não houver evidência\")\n  baseada_em OrigemRef[]\n  lacuna Lacuna?\n}\n\nclass ExplainabilityLimitsArtifact {\n  respostas LimitAnswer[]\n}\n\nclass LimitsInput {\n  stakeholders Stakeholder[]\n  necessidades ExplainabilityNeed[]\n  requisitos_complementares ComplementaryRequirement[]\n  checklist ChecklistQuestion[]\n}\n\nfunction DefineExplainabilityLimits(entrada: LimitsInput, contexto: ContextItem[]) -> ExplainabilityLimitsArtifact {\n  client OpenUPExpDefault\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você executa a tarefa 1.2.3 \"Define Explainability Scope and Limits\" do OpenUPExp,\n    respondendo ao checklist \"Limite da Explicabilidade\".\n\n    {{ RegrasNaoInvencao() }}\n\n    REGRAS ESPECÍFICAS\n    - Responda TODAS as perguntas do checklist, na mesma ordem, copiando 'dimensao' e 'pergunta'.\n    - Sem evidência para responder, 'resposta' = null e preencha 'lacuna' com a pergunta\n      que o Engenheiro deve levar aos stakeholders.\n    - 'baseada_em' deve citar os IDs (STK-n, NEED-n, CR-n) que sustentam a resposta.\n\n    {{ _.role(\"user\") }}\n    CHECKLIST\n    {{ entrada.checklist }}\n\n    STAKEHOLDERS\n    {{ entrada.stakeholders }}\n\n    NECESSIDADES\n    {{ entrada.necessidades }}\n\n    REQUISITOS COMPLEMENTARES\n    {{ entrada.requisitos_complementares }}\n\n    {{ ContextoAdicional(contexto) }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
    "vision_1_3_validate.baml": "// Subprocesso 1.3 Validate Explainability Vision\n// A revisão (1.3.1) e a decisão do gateway são humanas. Aqui fica apenas o digest\n// gerado na consolidação (1.3.2), usado como contexto auxiliar das fases seguintes.\n\nclass PhaseDigest {\n  resumo string @description(\"Resumo compacto (até ~600 palavras) da fase aprovada\")\n  ids_cobertos string[] @description(\"Todos os IDs de itens mencionados no resumo\")\n}\n\nclass DigestInput {\n  documento string @description(\"Documento aprovado da fase, em Markdown\")\n  ids_obrigatorios string[] @description(\"IDs que DEVEM ser mencionados no resumo\")\n}\n\nfunction BuildPhaseDigest(entrada: DigestInput, contexto: ContextItem[]) -> PhaseDigest {\n  client OpenUPExpCheap\n  prompt #\"\n    {{ _.role(\"system\") }}\n    Você resume um documento aprovado do processo OpenUPExp para servir de contexto auxiliar às\n    fases seguintes. O resumo NÃO substitui o documento: os dados completos continuam disponíveis.\n\n    REGRAS\n    - Mencione explicitamente, por ID, TODOS os itens listados em ids_obrigatorios.\n    - Não acrescente informação que não esteja no documento.\n    - Preserve lacunas relevantes (o que ainda requer investigação).\n\n    {{ _.role(\"user\") }}\n    IDS OBRIGATÓRIOS\n    {{ entrada.ids_obrigatorios }}\n\n    DOCUMENTO APROVADO\n    {{ entrada.documento }}\n\n    {{ ctx.output_format }}\n  \"#\n}\n",
}

